sealed class SpeechBridge : IDisposable {
 readonly WebView2 web; readonly Form owner; readonly string source; readonly System.Web.Script.Serialization.JavaScriptSerializer json=new System.Web.Script.Serialization.JavaScriptSerializer{MaxJsonLength=30000000};
 string executable,model,checkDirectory; System.Diagnostics.Process process; bool disposed;
 readonly string settings=Program.Check!=null?Path.Combine(Program.Check,"speech-settings.json"):Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Jago","Pulse","speech.json");
 public SpeechBridge(WebView2 view,Form form,string page){web=view;owner=form;source=new Uri(page).AbsoluteUri;try{var data=json.Deserialize<System.Collections.Generic.Dictionary<string,string>>(File.ReadAllText(settings));executable=data["executable"];model=data["model"];}catch{}if(!Connected()){string optional=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Transcription");if(File.Exists(Path.Combine(optional,"whisper-cli.exe"))&&File.Exists(Path.Combine(optional,"ggml-tiny.en.bin"))){executable=Path.Combine(optional,"whisper-cli.exe");model=Path.Combine(optional,"ggml-tiny.en.bin");}}web.CoreWebView2.WebMessageReceived+=Receive;}
 public async System.Threading.Tasks.Task Check(string directory){var data=json.Deserialize<System.Collections.Generic.Dictionary<string,string>>(File.ReadAllText(Path.Combine(directory,"speech-check.json")));if(data.ContainsKey("executable"))executable=data["executable"];if(data.ContainsKey("model"))model=data["model"];checkDirectory=directory;string wav=Convert.ToBase64String(File.ReadAllBytes(data["audio"]));await web.ExecuteScriptAsync("chrome.webview.postMessage("+json.Serialize(new{kind="speech-transcribe",wav=wav})+")");}
 void Send(string message,bool done,string srt=null){if(checkDirectory!=null&&done){File.WriteAllText(Path.Combine(checkDirectory,"native-speech.json"),json.Serialize(new{ok=srt!=null,message=message,srt=srt,executable=executable,model=model}));owner.BeginInvoke(new Action(()=>owner.Close()));}if(disposed||owner.IsDisposed)return;web.CoreWebView2.PostWebMessageAsJson(json.Serialize(new{kind="speech",message=message,done=done,srt=srt}));}
 bool Connected(){return File.Exists(executable)&&File.Exists(model);}
 async void Receive(object sender,CoreWebView2WebMessageReceivedEventArgs args){if(!String.Equals(args.Source,source,StringComparison.OrdinalIgnoreCase)||disposed)return;try{var data=json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(args.WebMessageAsJson);string kind=data.ContainsKey("kind")?Convert.ToString(data["kind"]):"";if(kind=="speech-status"){Send(Connected()?"Local transcription connected. Review all generated words and timing.":"Optional: select Offline lyric transcription under Pulse in setup, or connect your own whisper.cpp engine and model. Timed text import works without them.",true);return;}if(kind=="speech-cancel"){if(process!=null&&!process.HasExited)process.Kill();return;}if(kind=="speech-setup"){if(process!=null){Send("Wait for transcription or cancel it first.",false);return;}using(var pick=new OpenFileDialog{Title="Choose whisper.cpp whisper-cli.exe",Filter="Whisper CLI (whisper-cli.exe)|whisper-cli.exe",CheckFileExists=true}){if(pick.ShowDialog(owner)!=DialogResult.OK)return;string chosen=pick.FileName;using(var chooseModel=new OpenFileDialog{Title="Choose a compatible ggml Whisper model",Filter="Whisper model (*.bin)|*.bin",CheckFileExists=true}){if(chooseModel.ShowDialog(owner)!=DialogResult.OK)return;executable=chosen;model=chooseModel.FileName;Directory.CreateDirectory(Path.GetDirectoryName(settings));File.WriteAllText(settings,json.Serialize(new{executable=executable,model=model}));}}Send("Local transcription connected. Audio stays on this computer.",true);return;}if(kind!="speech-transcribe")return;if(process!=null){Send("A transcription is already running.",false);return;}if(!Connected()){Send("Select Offline lyric transcription under Pulse in setup and restart Pulse, or connect a compatible local engine and model.",true);return;}string encoded=Convert.ToString(data["wav"]);if(encoded.Length>26000000)throw new Exception("Keep transcription within ten minutes.");byte[] audio=Convert.FromBase64String(encoded);if(audio.Length<44||audio.Length>19200044||System.Text.Encoding.ASCII.GetString(audio,0,4)!="RIFF"||BitConverter.ToInt32(audio,24)!=16000||BitConverter.ToInt16(audio,22)!=1)throw new Exception("Use mono 16 kHz WAV audio.");string root=Path.Combine(Path.GetTempPath(),"Jago-Pulse-Speech"),job=Path.Combine(root,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(job);try{string input=Path.Combine(job,"input.wav"),output=Path.Combine(job,"draft");File.WriteAllBytes(input,audio);var start=new System.Diagnostics.ProcessStartInfo(executable,"-m \""+model+"\" -f \""+input+"\" -osrt -ml 60 -sow -of \""+output+"\" -l auto"){UseShellExecute=false,CreateNoWindow=true,WindowStyle=System.Diagnostics.ProcessWindowStyle.Hidden,RedirectStandardError=true,RedirectStandardOutput=true,WorkingDirectory=Path.GetDirectoryName(executable)};process=new System.Diagnostics.Process{StartInfo=start};process.Start();var stderr=process.StandardError.ReadToEndAsync();var stdout=process.StandardOutput.ReadToEndAsync();bool exited=await System.Threading.Tasks.Task.Run(()=>process.WaitForExit(300000));if(!exited){process.Kill();throw new Exception("Transcription timed out after five minutes. Try a shorter track or a smaller model.");}await System.Threading.Tasks.Task.WhenAll(stderr,stdout);if(process.ExitCode!=0)throw new Exception("Transcription stopped or failed. Check the model and CLI compatibility.");string srt=output+".srt";if(!File.Exists(srt))throw new Exception("The transcription tool did not produce timed text.");Send("Draft transcript ready. Check words and timing, especially sung vocals.",true,File.ReadAllText(srt));}finally{if(process!=null){process.Dispose();process=null;}foreach(string name in new[]{"input.wav","draft.srt"}){string path=Path.Combine(job,name);if(File.Exists(path))File.Delete(path);}if(Directory.Exists(job)&&Directory.GetFileSystemEntries(job).Length==0)Directory.Delete(job);}}catch(Exception error){Send(error.Message,true);}}
 public void Dispose(){disposed=true;try{if(process!=null&&!process.HasExited)process.Kill();}catch{}}
}

