internal static class JagoHostSecurity {
 internal static bool Trusted(string candidate,string document){
  System.Uri value,expected;if(!System.Uri.TryCreate(candidate,System.UriKind.Absolute,out value)||!System.Uri.TryCreate(document,System.UriKind.Absolute,out expected)||value.UserInfo.Length!=0)return false;
  // Only the application document can call native operations; sibling pages are not application code.
  return value.Scheme==expected.Scheme&&value.Host.Equals(expected.Host,System.StringComparison.OrdinalIgnoreCase)&&value.Port==expected.Port&&value.AbsolutePath.Equals(expected.AbsolutePath,System.StringComparison.OrdinalIgnoreCase)&&value.Query.Length==0;
 }
 internal static string Document(string key){string host=key=="wobble"?"jagoloopstudio":key=="worldbuilding"?"jagoworld":key=="music"?"jagomusic":"jago"+key;return "https://"+host+".example/index.html";}
 internal static string ReadBounded(string path,long maximum){using(var stream=new System.IO.FileStream(path,System.IO.FileMode.Open,System.IO.FileAccess.Read,System.IO.FileShare.Read)){if(stream.Length>maximum)throw new System.IO.InvalidDataException("This file exceeds the supported size.");using(var reader=new System.IO.StreamReader(stream,System.Text.Encoding.UTF8,true)){var text=new System.Text.StringBuilder();char[] block=new char[8192];int n;while((n=reader.Read(block,0,block.Length))>0){if(text.Length+n>maximum)throw new System.IO.InvalidDataException("This file exceeds the supported size.");text.Append(block,0,n);}return text.ToString();}}}
 internal static string JsonArgument(string path,long maximum){string text=ReadBounded(path,maximum);var serializer=new System.Web.Script.Serialization.JavaScriptSerializer{MaxJsonLength=(int)maximum,RecursionLimit=512};serializer.DeserializeObject(text);return "JSON.parse("+serializer.Serialize(text)+")";}
 internal static void Locked(string path,System.Action action){string key;using(var sha=System.Security.Cryptography.SHA256.Create())key=System.BitConverter.ToString(sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(System.IO.Path.GetFullPath(path).ToUpperInvariant()))).Replace("-","");using(var gate=new System.Threading.Mutex(false,"Local\\JagoFile."+key)){bool held=false;try{try{held=gate.WaitOne(5000);}catch(System.Threading.AbandonedMutexException){held=true;}if(!held)throw new System.IO.IOException("This file is busy. Please try again.");action();}finally{if(held)gate.ReleaseMutex();}}}
 internal static void Atomic(string path,string text){Locked(path,()=>{string temp=System.IO.Path.Combine(System.IO.Path.GetDirectoryName(path),".jago-"+System.Guid.NewGuid().ToString("N")+".tmp");try{using(var stream=new System.IO.FileStream(temp,System.IO.FileMode.CreateNew,System.IO.FileAccess.Write,System.IO.FileShare.None)){using(var writer=new System.IO.StreamWriter(stream,new System.Text.UTF8Encoding(false))){writer.Write(text);writer.Flush();stream.Flush(true);}}if(System.IO.File.Exists(path))System.IO.File.Replace(temp,path,null);else System.IO.File.Move(temp,path);}finally{if(System.IO.File.Exists(temp))System.IO.File.Delete(temp);}});}
}
